mapper.update:
UPDATE matches
SET stadium_id = #{stadiumId}, 
    start_time = #{startTime}, 
    end_time = #{endTime}, 
    status = #{status}
WHERE id = #{id}

mapper.select:
SELECT * FROM matches


        ${key} LIKE CONCAT('%', #{word}, '%')



    ORDER BY ${order} ${orderDir}

select m.id, m.name, s.id, m.start_time, m.end_time, m.status, s.name as stadiumName, s.image
from matches m, stadium s
where m.id = #{id} AND m.stadium_id = s.id;

select m.id, m.name, s.id, m.start_time, m.end_time, m.status, s.name as stadiumName, s.image
from matches m, stadium s
where m.stadium_id = s.id;
